function validateCompleteness(flowchart) {
  const nodeMap = new Map(flowchart.nodes.map(n => [n.id, n]));
  const outgoingEdges = new Map();

  flowchart.edges.forEach(e => {
    if (!outgoingEdges.has(e.source)) {
      outgoingEdges.set(e.source, []);
    }
    outgoingEdges.get(e.source).push(e.target);
  });

  flowchart.nodes.forEach(node => {
    if (node.type !== 'endpoint' && node.type !== 'reference') {
      if (!outgoingEdges.has(node.id) || outgoingEdges.get(node.id).length === 0) {
        throw new Error(`Dead end at node: ${node.id}`);
      }
    }
  });
}
